#[test]
fn grams_per_second_per_square_meter() {
    for v in [1.0, 0.3, -42.75, 1e6, 123456.789] {
        // Generated conversion vs. the upstream formula, verbatim.
        let x: f64 = v;
        let base = x / 1e3;
        assert_close(
            MassFlux::from_grams_per_second_per_square_meter(v).as_base(),
            base,
            F64_TOL,
        );
        let x: f64 = base;
        let back = x * 1e3;
        assert_close(
            MassFlux::from_base(base).as_grams_per_second_per_square_meter(),
            back,
            F64_TOL,
        );
        assert_close(
            MassFlux::from_grams_per_second_per_square_meter(v)
                .as_grams_per_second_per_square_meter(),
            v,
            ROUND_TRIP_TOL,
        );
        // f32 storage.
        assert_close(
            MassFlux::from_grams_per_second_per_square_meter(v as f32).as_base() as f64,
            base,
            F32_TOL,
        );
        assert_close(
            MassFlux::from_base(base as f32).as_grams_per_second_per_square_meter() as f64,
            back,
            F32_TOL,
        );
    }
}

